#!/usr/bin/env python3
"""Generate the verified fictitious UX review download; refuses incomplete evidence."""
from pathlib import Path
import json, base64, html, sys
repo = Path(__file__).resolve().parents[1]
root = Path(sys.argv[1] if len(sys.argv) > 1 else repo / 'audit').resolve()
out = Path(sys.argv[2] if len(sys.argv) > 2 else '/tmp/feng-polish-downloads').resolve()
out.mkdir(exist_ok=True)
setup = 'iphone390-dark'
inv = json.loads((repo / 'scripts/feng-polish-screen-inventory.json').read_text())
matrix = json.loads((repo / 'docs/final-polish-verification.json').read_text())
preview = '--preview' in sys.argv[3:]
summary = json.loads((root / 'after/summary.json').read_text()) if (root / 'after/summary.json').exists() else {}
if not preview:
    assert summary['gate'] == 'PASS' and summary['completeEvidence']
    assert all((i['status'] == 'Fixed' and (not i['verificationPending']) for i in matrix['items']))
    visual = json.loads((root / 'visual-contact-sheets/review.json').read_text())
    low = json.loads((root / 'low-justifications.json').read_text())
    ci = json.loads((root / 'verification/ci.json').read_text())
    build = json.loads((root / 'verification/build.json').read_text())
    lighthouse = json.loads((root / 'lighthouse/summary.json').read_text())
    assert summary['screenshots'] == 980 and visual['complete'] and visual['reviewedStates'] == 980
    assert low['complete'] and not low['unjustified']
    assert ci['status'] == 'pass' and ci['verifiedApplicationCommit'] == build['sourceCommit']
    assert len(lighthouse['scores']) == 6 and all(r['accessibility'] >= 95 and r['bestPractices'] >= 95 and r['entryScript'] == build['entryScript'] and build['entryStylesheet'] in r['stylesheets'] for r in lighthouse['scores'])

journey = ['first-launch', 'home-empty', 'import-pick', 'import-check', 'import-review-one', 'import-review-one-expanded', 'import-review-four', 'import-amex-expanded', 'import-barclaycard-expanded', 'import-revolut-expanded', 'home-after-import', 'sorting-sheet', 'sorting-undo-toast', 'transactions-list', 'transaction-filters', 'transaction-filters-date', 'transaction-query-builder', 'transaction-search-empty', 'transaction-detail', 'transaction-tags', 'split-remaining', 'split-balanced', 'refund-detail', 'refund-picker', 'manual-transaction', 'analyse-overview', 'analyse-category', 'analyse-property', 'analyse-property-report', 'analyse-reports', 'self-assessment', 'planning-budgets', 'budget-status', 'planning-pots', 'planning-calendar', 'planning-debt', 'debt-calculated', 'planning-forecast', 'what-if', 'subscriptions', 'subscription-evidence', 'monthly-review-1', 'monthly-review-2', 'monthly-review-3', 'monthly-review-4', 'settings-home', 'settings-backup', 'backup-protected-editor', 'backup-protected-ready', 'backup-saved-toast', 'restore-unlock', 'restore-preview', 'restore-acknowledged']
known = {s['id']: s for s in inv['states']}
order = [s for s in journey if s in known] + [s['id'] for s in inv['states'] if s['id'] not in journey]
assert len(order) == 140 and len(set(order)) == 140
journeyData = {r['id']: r for r in json.loads((repo / 'docs/final-polish-journey.json').read_text())['states']}
rows = []
for sid in order:
    row = {'id': sid, 'journey': journeyData[sid], 'title': known[sid]['title'], 'findings': [{'id': i['id'], 'status': i['status'], 'observation': i['observation']} for i in matrix['items'] if sid in i['states']]}
    for phase in ['before', 'after']:
        data = json.loads((root / phase / setup / (sid + '.json')).read_text())
        els = data['audit']['elements']
        row[phase] = {'viewport': 'data:image/png;base64,' + base64.b64encode((root / phase / data['image']).read_bytes()).decode(), 'full': 'data:image/png;base64,' + base64.b64encode((root / phase / data['fullImage']).read_bytes()).decode(), 'cards': data['audit']['measurements'].get('cardSamples', []), 'elements': [{k: e.get(k) for k in ['name', 'selectedOption', 'kind', 'tag', 'type', 'x', 'y', 'w', 'h', 'hitW', 'hitH', 'fontSize', 'lineHeight', 'selector']} for e in els], 'capturedAt': data['capturedAt'], 'entryScript': data['metrics']['entryScript'], 'issues': data['audit']['issues']}
    rows.append(row)
payload = json.dumps(rows, ensure_ascii=False, separators=(',', ':')).replace('<', '\\u003c')
head = '<!doctype html><html lang="en-GB"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Feng Finance 2.2.7 · complete mobile UX review</title><style>body{font:16px/1.5 system-ui;color:#172034;background:#edf1f7;margin:0}header,main{max-width:1400px;margin:auto;padding:24px}header{position:sticky;top:0;background:#fff;border-bottom:1px solid #c2ccda;z-index:2}h1{font-size:24px;line-height:1.3;margin:0 0 8px}p{max-width:90ch}button,select,input{min-height:44px;font:inherit;border:1px solid #8594aa;background:white;color:#172034;border-radius:8px;padding:8px}nav{display:flex;gap:12px;flex-wrap:wrap;align-items:center}select{max-width:100%;flex:1}article,.panel{background:#fff;border:1px solid #c2ccda;border-radius:12px;padding:20px;margin:16px 0}.pair{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:24px}.shot{display:flex;flex-direction:column;align-items:flex-start}.shot img{max-width:100%;height:auto;border:1px solid #a5b1c2;margin:12px 0;cursor:zoom-in}button:focus-visible,select:focus-visible,a:focus-visible{outline:3px solid #315c9c;outline-offset:3px}.scroll{overflow:auto}table{border-collapse:collapse;min-width:650px;width:100%}th,td{text-align:left;border-bottom:1px solid #c2ccda;padding:8px}td.num,th.num{text-align:right;white-space:nowrap;font-variant-numeric:tabular-nums}code{font-size:13px;white-space:normal;overflow-wrap:break-word}dialog{border:0;max-width:95vw;max-height:95vh;padding:16px;overflow:auto}dialog img{max-width:none}dialog::backdrop{background:#000a}#close{position:sticky;top:0;display:block}small{font-size:13px}.controls{display:flex;gap:8px;align-items:center;flex-wrap:wrap}@media(max-width:750px){.pair{grid-template-columns:1fr}header,main{padding:16px}header{position:static}}</style><header><h1>Feng Finance 2.2.7 · complete mobile UX review</h1><p>140 actual UI states, 390 × 844 CSS px, WebKit, dark theme. Fictitious records only. All screenshots and measurements are embedded: this file works offline without a server. Use the seven-setup ZIPs for the other mobile, large-text, light and desktop captures.</p><nav aria-label="Review states"><button id="prev">Previous</button><select id="state" aria-label="Choose screen or journey step"></select><button id="next">Next</button><span id="progress"></span></nav></header><main><article><h2 id="title"></h2><p id="stateid"></p><div id="journey"></div><p>The journey begins with first launch, native file selection, checking, review, import confirmation, Home and categorisation. Later states cover each analysis/planning screen, settings sheet, empty state and financial error branch. These are captured application states, not interactive app mockups.</p><div class="controls"><label>Image view <select id="view"><option value="viewport">Initial viewport</option><option value="full">Full page</option></select></label><label>Elements <select id="kind"><option value="all">All measured elements</option><option value="interactive">Controls only</option><option value="text">Text only</option></select></label></div><div class="pair" id="shots"></div></article><article><h2>Review findings and interface behaviour</h2><div id="findings"></div></article><article><h2>Element sizes and positions</h2><p>CSS pixels, not screenshot-image pixels. Hit area includes the associated label where applicable. Fixed sheets scroll internally, so their full-page screenshot can remain viewport-height; the element measurements include their rendered off-screen content. Measurements preserve exact source values and do not certify physical iPhone or VoiceOver behaviour.</p><div class="scroll"><table><thead><tr><th>Element</th><th>Kind</th><th class="num">Width × height</th><th class="num">Hit width × height</th><th class="num">Font</th><th class="num">X / Y</th></tr></thead><tbody id="elements"></tbody></table></div></article><article><h2>Card spacing and shared sizing</h2><p>These card edges and radii are measured in the selected after state. Controls above retain their actual dimensions; the shared values below are minimum sizes and grow for enlarged text.</p><div class="scroll"><table><thead><tr><th>Card</th><th>Left / right margin</th><th>Radius</th></tr></thead><tbody id="cards"></tbody></table></div><p>Mobile content edge 16px · primary action 48px · secondary action 44px · input 48px with 16px text · chip visual 32px with 44px hit area · segment visual 36px with 44px hit area · one-line list row at least 52px, two-line at least 64px · card radius 16px mobile, 12px desktop · desktop sheet 420px. Original captures and measurements show actual values at each size.</p></article><article><h2>Verification and remaining gates</h2><p>Final build: 0 high and 0 medium findings across 980 captures on seven setups. Every retained low is individually justified in the full audit. Lighthouse accessibility 100 and best practices 96 on Home, Transactions and Settings in both themes. See FINAL-POLISH-REPORT.md for all 44 blockers, all 205 findings, test evidence and explicit scope exceptions.</p><p>Physical iPhone installation/Files/safe-area checks, VoiceOver, three-device hardware evidence, beta-volunteer exit and owner sign-off remain manual. The owner approved confirmation without Undo for PIN/passkey changes. Lock-delay changes retain Undo.</p></article></main><dialog id="zoom"><button id="close">Close full-size image</button><img id="large" alt="Full-size screenshot"></dialog>'
script = '<script type="application/json" id="data">PAYLOAD</script><script>const rows=JSON.parse(document.querySelector(\'#data\').textContent),state=document.querySelector(\'#state\'),view=document.querySelector(\'#view\'),kind=document.querySelector(\'#kind\');const el=(tag,text)=>{const e=document.createElement(tag);if(text!==undefined)e.textContent=text;return e};rows.forEach((r,i)=>{const o=el(\'option\',(i+1)+\'. \'+r.title);o.value=r.id;state.append(o)});function draw(){const i=Math.max(0,rows.findIndex(r=>r.id===state.value)),r=rows[i];document.querySelector(\'#title\').textContent=r.title;document.querySelector(\'#stateid\').textContent=r.id;const journey=document.querySelector(\'#journey\');journey.replaceChildren();[\'entry\',\'action\',\'result\'].forEach((key)=>{const p=el(\'p\');p.append(el(\'strong\',({entry:\'Entry: \',action:\'Interaction: \',result:\'Result: \'})[key]),document.createTextNode(r.journey[key]));journey.append(p)});document.querySelector(\'#progress\').textContent=(i+1)+\' of \'+rows.length;document.querySelector(\'#prev\').disabled=i===0;document.querySelector(\'#next\').disabled=i===rows.length-1;const shots=document.querySelector(\'#shots\');shots.replaceChildren();[\'before\',\'after\'].forEach(p=>{const box=el(\'div\');box.className=\'shot\';box.append(el(\'h3\',p===\'before\'?\'Before · v2.2.6\':\'After · v2.2.7\'));const img=el(\'img\');img.alt=p+\' \'+r.title;img.src=r[p][view.value];img.width=390;img.onclick=()=>{document.querySelector(\'#large\').src=img.src;document.querySelector(\'#zoom\').showModal()};box.append(img,el(\'small\',r[p].capturedAt+\' · \'+r[p].entryScript));shots.append(box)});const f=document.querySelector(\'#findings\');f.replaceChildren();if(!r.findings.length)f.append(el(\'p\',\'Supporting or error-state evidence. The complete audit includes its geometry and accessibility checks.\'));r.findings.forEach(x=>{f.append(el(\'h3\',x.id+\' · \'+x.status),el(\'p\',x.observation))});const body=document.querySelector(\'#elements\');body.replaceChildren();r.after.elements.filter(e=>kind.value===\'all\'||e.kind===kind.value).forEach(e=>{const tr=el(\'tr\');const name=el(\'td\',e.selectedOption||e.name||e.selector);name.title=e.selector;tr.append(name,el(\'td\',e.kind+\' / \'+e.tag));[[e.w,e.h],[e.hitW,e.hitH],[e.fontSize],[e.x,e.y]].forEach(values=>{const td=el(\'td\',values.map(v=>typeof v===\'number\'?Math.round(v*100)/100:v??\'\').join(\' × \'));td.className=\'num\';tr.append(td)});body.append(tr)});const cards=document.querySelector(\'#cards\');cards.replaceChildren();r.after.cards.forEach(c=>{const tr=el(\'tr\');tr.append(el(\'td\',c.selector),el(\'td\',c.leftMargin+\' / \'+c.rightMargin),el(\'td\',c.radius));cards.append(tr)});history.replaceState(null,\'\',\'#\'+r.id)}state.onchange=()=>{draw();window.scrollTo(0,0)};view.onchange=draw;kind.onchange=draw;document.querySelector(\'#prev\').onclick=()=>{state.selectedIndex--;draw();window.scrollTo(0,0)};document.querySelector(\'#next\').onclick=()=>{state.selectedIndex++;draw();window.scrollTo(0,0)};document.querySelector(\'#close\').onclick=()=>document.querySelector(\'#zoom\').close();if(rows.some(r=>r.id===location.hash.slice(1)))state.value=location.hash.slice(1);draw();</script></html>'.replace('PAYLOAD', payload)
if not preview:
    head = head.replace('Lighthouse accessibility 100 and best practices 96', 'Lighthouse accessibility at least ' + str(min(r['accessibility'] for r in lighthouse['scores'])) + ' and best practices at least ' + str(min(r['bestPractices'] for r in lighthouse['scores'])))
if preview:
    head = head.replace('<h1>Feng Finance', '<p><strong>PREVIEW: final seven-setup verification is still running. Do not treat this file as release approval.</strong></p><h1>Feng Finance').replace('Final build: 0 high and 0 medium findings across 980 captures on seven setups.', 'Preview of the completed mobile captures; final full-matrix verification is pending.').replace('Lighthouse accessibility 100 and best practices 96 on Home, Transactions and Settings in both themes.', 'Final Lighthouse verification is pending.')
p = out / ('Feng-Finance-2.2.7-Mobile-UX-PREVIEW.html' if preview else 'Feng-Finance-2.2.7-Mobile-UX-Review.html')
p.write_text(head + script)
print(json.dumps({'file': str(p), 'bytes': p.stat().st_size, 'states': len(rows)}))
